import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Edit, Trash2, Shield, User, Lock, ChevronDown, ChevronUp } from 'lucide-react';
import { useUserStore } from '../stores/userStore';

interface User {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'editor' | 'viewer';
  lastActive: string;
  status: 'active' | 'suspended';
}

interface Role {
  value: 'admin' | 'editor' | 'viewer';
  label: string;
  permissions: string[];
}

const UserManagement = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedUser, setExpandedUser] = useState<string | null>(null);
  const [editUser, setEditUser] = useState<User | null>(null);
  const navigate = useNavigate();
  const { currentUser } = useUserStore();

  const roles: Role[] = [
    {
      value: 'admin',
      label: 'Administrator',
      permissions: ['Manage users', 'Edit all content', 'View all data', 'System configuration'],
    },
    {
      value: 'editor',
      label: 'Editor',
      permissions: ['Edit content', 'View all data', 'Publish content'],
    },
    {
      value: 'viewer',
      label: 'Viewer',
      permissions: ['View content', 'View reports'],
    },
  ];

  useEffect(() => {
    if (currentUser?.role !== 'admin') {
      navigate('/');
      return;
    }

    // Simulate API fetch
    const fetchUsers = async () => {
      try {
        setLoading(true);
        // Mock data - in real app this would be an API call
        const mockUsers: User[] = [
          {
            id: '1',
            name: 'Alex Johnson',
            email: 'alex.johnson@example.com',
            role: 'admin',
            lastActive: '2023-05-15T10:30:00Z',
            status: 'active',
          },
          {
            id: '2',
            name: 'Maria Garcia',
            email: 'maria.garcia@example.com',
            role: 'editor',
            lastActive: '2023-05-14T15:45:00Z',
            status: 'active',
          },
          {
            id: '3',
            name: 'James Wilson',
            email: 'james.wilson@example.com',
            role: 'viewer',
            lastActive: '2023-05-10T09:15:00Z',
            status: 'active',
          },
          {
            id: '4',
            name: 'Sarah Lee',
            email: 'sarah.lee@example.com',
            role: 'editor',
            lastActive: '2023-04-28T14:20:00Z',
            status: 'suspended',
          },
        ];
        setUsers(mockUsers);
      } catch (err) {
        setError('Failed to load users. Please try again later.');
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [currentUser, navigate]);

  const handleEdit = (user: User) => {
    setEditUser(user);
  };

  const handleSave = () => {
    if (!editUser) return;

    setUsers(users.map(u => u.id === editUser.id ? editUser : u));
    setEditUser(null);
  };

  const handleRoleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    if (!editUser) return;

    const role = e.target.value as 'admin' | 'editor' | 'viewer';
    setEditUser({ ...editUser, role });
  };

  const handleStatusToggle = (userId: string) => {
    setUsers(users.map(user => 
      user.id === userId 
        ? { 
            ...user, 
            status: user.status === 'active' ? 'suspended' : 'active' 
          } 
        : user
    ));
  };

  const handleDelete = (userId: string) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      setUsers(users.filter(user => user.id !== userId));
    }
  };

  const toggleExpand = (userId: string) => {
    setExpandedUser(expandedUser === userId ? null : userId);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
